// Typed client facade (Ambidex spec §5, §7): `createClient` turns a generated procedure table
// into calls over one lazily opened connection.
//
//   import * as api from "./api.js";               // generated by rpc-gen
//   const client = createClient(api, autoTransport());
//   const rows = await client.query.execute({ sql }, { signal, timeoutMs: 5000 });
//
// - query / mutation: `Promise<Output>`. Rejects with an `RpcError` (see `errors.ts`).
// - subscription: `Subscription<Event>` (an `AsyncIterable` with `unsubscribe()`).
// - stream: `StreamCall` with `chunks()` and `result` (M1 shape only; credits and Arrow decoding
//   are M2, see `StreamHandle`).
//
// Connections: one at a time, opened on the first call (or `$connect()`), replaced on the next
// call after it closes. Calls in flight when a connection closes fail with `Unavailable`; nothing
// is replayed, so a mutation is never sent twice by the runtime.
//
// Cancellation (spec §7, Open question 21): aborting the call's `AbortSignal` sends `Cancel` once
// and rejects the call at once with a local `Cancelled`, without waiting for the server's reply;
// an abort before the call was sent sends nothing. The server owns the deadline: `timeoutMs`
// travels as `timeout_ms` and the server answers `DeadlineExceeded`. The runtime only keeps a
// safety timer at the procedure's effective deadline plus `timeoutSlackMs`, for a server that never
// answers.

import type { CallOptions, Client, ProcedureKind, ProcedureLike } from "./contract.js";
import { Connection, type HelloAck } from "./connection.js";
import { RpcError, localError } from "./errors.js";
import { FLAG_BINARY, type Frame, Kind, PROTOCOL_VERSION, parseJson } from "./frame.js";
import type { Transport } from "./transport.js";

/** Version string sent as `Hello.client_version`. */
export const CLIENT_VERSION = "@byterygon/ambidex/0.0.0";

/** What a generated `api.ts` exports, used as `import * as api from "./api.js"`. */
export interface GeneratedApi<T = unknown> {
  readonly API: string;
  readonly SCHEMA_HASH: string;
  readonly PROTOCOL: number;
  readonly procedures: T;
}

export interface ClientOptions {
  /** Time allowed to open the pipe and complete the handshake. Default 10 s (server default). */
  readonly helloTimeoutMs?: number;
  /**
   * How long after a call's effective deadline the runtime waits for the server's
   * `DeadlineExceeded` before failing the call locally. Covers the server's cancel grace and
   * latency. Default 5000 ms.
   */
  readonly timeoutSlackMs?: number;
  /**
   * Events (or chunks) buffered per subscription (or stream) the consumer has not read yet. When
   * exceeded the subscription ends with `ResourceExhausted`. Default 1024.
   */
  readonly maxBufferedEvents?: number;
  /** Overrides `Hello.client_version`. */
  readonly clientVersion?: string;
}

/** Control methods on every client. `$` cannot start a procedure name segment, so no clash. */
export interface ClientControl {
  /** Opens the connection now (otherwise the first call does) and returns the HelloAck. */
  $connect(): Promise<HelloAck>;
  /** Round trip of a Ping on the current connection, in milliseconds. */
  $ping(): Promise<number>;
  /**
   * Closes the client: sends Goaway, fails calls in flight with a local `Cancelled`, ends
   * subscriptions. Later calls fail with `Unavailable`.
   */
  $close(): void;
}

export type AmbidexClient<T> = Client<T> & ClientControl;

const KINDS: ReadonlySet<string> = new Set<ProcedureKind>([
  "query",
  "mutation",
  "subscription",
  "stream",
]);

function isProcedure(value: unknown): value is ProcedureLike {
  if (typeof value !== "object" || value === null) return false;
  const v = value as Record<string, unknown>;
  return typeof v["name"] === "string" && typeof v["kind"] === "string" && KINDS.has(v["kind"]);
}

function isGeneratedApi(value: unknown): value is GeneratedApi {
  if (typeof value !== "object" || value === null) return false;
  const v = value as Record<string, unknown>;
  return (
    typeof v["API"] === "string" &&
    typeof v["SCHEMA_HASH"] === "string" &&
    typeof v["PROTOCOL"] === "number" &&
    typeof v["procedures"] === "object"
  );
}

/** Identity for `createClient` when passing a bare procedure table. */
export interface ApiIdentity {
  readonly api: string;
  readonly schemaHash: string;
  readonly protocol?: number;
}

/**
 * A client for a generated API. Pass the generated module (`import * as api from "./api.js"`),
 * or its `procedures` table with `{ api: API, schemaHash: SCHEMA_HASH }`.
 */
export function createClient<T>(
  api: GeneratedApi<T>,
  transport: Transport,
  options?: ClientOptions,
): AmbidexClient<T>;
export function createClient<T>(
  procedures: T,
  transport: Transport,
  options: ClientOptions & ApiIdentity,
): AmbidexClient<T>;
export function createClient(
  api: unknown,
  transport: Transport,
  options: ClientOptions & Partial<ApiIdentity> = {},
): AmbidexClient<unknown> {
  let procedures: unknown;
  let identity: { api: string; schemaHash: string; protocol: number };
  if (isGeneratedApi(api)) {
    procedures = api.procedures;
    identity = { api: api.API, schemaHash: api.SCHEMA_HASH, protocol: api.PROTOCOL };
  } else {
    if (options.api === undefined || options.schemaHash === undefined) {
      throw new TypeError("createClient: pass the generated module, or api and schemaHash");
    }
    procedures = api;
    identity = {
      api: options.api,
      schemaHash: options.schemaHash,
      protocol: options.protocol ?? PROTOCOL_VERSION,
    };
  }
  if (identity.protocol !== PROTOCOL_VERSION) {
    throw new TypeError(
      `createClient: generated for protocol ${identity.protocol}, runtime speaks ${PROTOCOL_VERSION}`,
    );
  }
  const runtime = new Runtime(transport, {
    hello: {
      api: identity.api,
      schemaHash: identity.schemaHash,
      protocol: identity.protocol,
      clientVersion: options.clientVersion ?? CLIENT_VERSION,
    },
    helloTimeoutMs: options.helloTimeoutMs ?? 10_000,
    timeoutSlackMs: options.timeoutSlackMs ?? 5_000,
    maxBufferedEvents: options.maxBufferedEvents ?? 1024,
  });
  const client = build(procedures, runtime) as Record<string, unknown>;
  runtimes.set(client, runtime);
  const control: ClientControl = {
    $connect: () => runtime.connection().then((conn) => conn.ack),
    $ping: () => runtime.connection().then((conn) => conn.ping()),
    $close: () => runtime.close(),
  };
  return Object.freeze(Object.assign(client, control)) as AmbidexClient<unknown>;
}

const runtimes = new WeakMap<object, Runtime>();

/** Internal state of a client, for leak tests. Not exported from the package. */
export function debugState(client: object): { live: number; activeCalls: number } | undefined {
  return runtimes.get(client)?.state();
}

function build(table: unknown, runtime: Runtime): unknown {
  if (typeof table !== "object" || table === null) {
    throw new TypeError("createClient: not a procedure table");
  }
  const out: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(table)) {
    if (isProcedure(value)) {
      out[key] = procedureCall(value, runtime);
    } else {
      out[key] = Object.freeze(build(value, runtime));
    }
  }
  return out;
}

function procedureCall(def: ProcedureLike, runtime: Runtime): unknown {
  switch (def.kind) {
    case "query":
    case "mutation":
      return (input?: unknown, opts?: CallOptions) => runtime.call(def, input, opts);
    case "subscription":
      return (input?: unknown, opts?: CallOptions) => runtime.subscribe(def, input, opts);
    case "stream":
      return (input?: unknown, opts?: CallOptions) => runtime.stream(def, input, opts);
  }
}

interface RuntimeOptions {
  readonly hello: {
    readonly api: string;
    readonly schemaHash: string;
    readonly protocol: number;
    readonly clientVersion: string;
  };
  readonly helloTimeoutMs: number;
  readonly timeoutSlackMs: number;
  readonly maxBufferedEvents: number;
}

/** `setTimeout` takes at most a signed 32-bit delay. */
const MAX_TIMER_MS = 0x7fff_ffff;

/** The `Call`/`Subscribe` payload: `{procedure, input, timeout_ms?}` (spec Open questions 14b, 21a). */
function callPayload(def: ProcedureLike, input: unknown, timeoutMs: number | undefined): unknown {
  const payload: Record<string, unknown> = {
    procedure: def.name,
    // A Rust `()` input is `null`; an omitted input is the same.
    input: input === undefined ? null : input,
  };
  if (timeoutMs !== undefined) payload["timeout_ms"] = timeoutMs;
  return payload;
}

function validateTimeout(timeoutMs: number | undefined, procedure: string): RpcError | undefined {
  if (timeoutMs === undefined) return undefined;
  if (!Number.isSafeInteger(timeoutMs) || timeoutMs < 0) {
    return localError("InvalidArgument", "timeoutMs must be a non-negative integer", {
      procedure,
    });
  }
  return undefined;
}

function cancelled(procedure: string): RpcError {
  return localError("Cancelled", "call cancelled", { procedure });
}

/** Reads the generated table's timeouts, if present (`ProcedureDef.timeoutDefaultMs/MaxMs`). */
function deadlineMs(def: ProcedureLike, timeoutMs: number | undefined): number | undefined {
  const d = def as { timeoutDefaultMs?: unknown; timeoutMaxMs?: unknown };
  const max = typeof d.timeoutMaxMs === "number" ? d.timeoutMaxMs : undefined;
  const dflt = typeof d.timeoutDefaultMs === "number" ? d.timeoutDefaultMs : undefined;
  const requested = timeoutMs ?? dflt;
  if (requested === undefined) return max;
  return max === undefined ? requested : Math.min(requested, max);
}

class Runtime {
  #transport: Transport;
  #options: RuntimeOptions;
  #current: Promise<Connection> | undefined;
  #open: Connection | undefined;
  #closed = false;
  /** Everything in flight, so `close()` can end it with `Cancelled`. */
  #live = new Set<(error: RpcError) => void>();

  constructor(transport: Transport, options: RuntimeOptions) {
    this.#transport = transport;
    this.#options = options;
  }

  /** The open connection, opening one if there is none or the last one stopped taking calls. */
  connection(): Promise<Connection> {
    if (this.#closed) return Promise.reject(localError("Unavailable", "client closed"));
    const current = this.#current;
    if (current !== undefined) {
      return current.then((conn) => (conn.accepting ? conn : this.#reopen(current)));
    }
    return this.#reopen(undefined);
  }

  #reopen(stale: Promise<Connection> | undefined): Promise<Connection> {
    if (this.#current !== stale) return this.connection();
    const opening = Connection.open(this.#transport, {
      hello: this.#options.hello,
      helloTimeoutMs: this.#options.helloTimeoutMs,
    });
    this.#current = opening;
    opening.then(
      (conn) => {
        if (this.#current === opening) this.#open = conn;
        conn.onClosed(() => {
          if (this.#current === opening) this.#current = undefined;
          if (this.#open === conn) this.#open = undefined;
        });
        if (this.#closed) conn.close(localError("Cancelled", "client closed"));
      },
      () => {
        // The failed attempt is reported to the calls that waited on it; the next call retries.
        if (this.#current === opening) this.#current = undefined;
      },
    );
    return opening;
  }

  state(): { live: number; activeCalls: number } {
    return { live: this.#live.size, activeCalls: this.#open?.activeCalls ?? 0 };
  }

  close(): void {
    if (this.#closed) return;
    this.#closed = true;
    const error = localError("Cancelled", "client closed");
    for (const end of [...this.#live]) end(error);
    const current = this.#current;
    this.#current = undefined;
    current?.then(
      (conn) => conn.close(error),
      () => {},
    );
  }

  /** Registers on a connection that accepts calls, replacing one whose ids ran out. */
  async #register(handler: Parameters<Connection["register"]>[0]): Promise<[Connection, number]> {
    for (;;) {
      const conn = await this.connection();
      const id = conn.register(handler);
      if (id !== undefined) return [conn, id];
      // Closed or ids exhausted between the check and now: the next round opens a new one.
    }
  }

  call(def: ProcedureLike, input: unknown, opts: CallOptions = {}): Promise<unknown> {
    const name = def.name;
    const invalid = validateTimeout(opts.timeoutMs, name);
    if (invalid !== undefined) return Promise.reject(invalid);
    const { signal } = opts;
    if (signal?.aborted) return Promise.reject(cancelled(name));
    if (this.#closed)
      return Promise.reject(localError("Unavailable", "client closed", { procedure: name }));

    return new Promise<unknown>((resolve, reject) => {
      let settled = false;
      let conn: Connection | undefined;
      let id: number | undefined;
      let timer: ReturnType<typeof setTimeout> | undefined;

      const finish = (outcome: () => void, release: "keep" | "release" | "cancel"): void => {
        if (settled) return;
        settled = true;
        signal?.removeEventListener("abort", onAbort);
        if (timer !== undefined) clearTimeout(timer);
        this.#live.delete(end);
        if (conn !== undefined && id !== undefined) {
          if (release === "cancel") conn.cancel(id);
          else if (release === "release") conn.release(id);
        }
        outcome();
      };
      const onAbort = (): void => finish(() => reject(cancelled(name)), "cancel");
      const end = (error: RpcError): void =>
        finish(() => reject(error.forProcedure(name)), "cancel");

      signal?.addEventListener("abort", onAbort, { once: true });
      this.#live.add(end);

      const handler = {
        frame: (frame: Frame) => {
          switch (frame.kind) {
            case Kind.Result: {
              let value: unknown;
              try {
                value = parseJson(frame.payload);
              } catch {
                return finish(
                  () => reject(localError("Internal", "malformed result", { procedure: name })),
                  "release",
                );
              }
              return finish(() => resolve(value), "release");
            }
            case Kind.Error:
              return finish(
                () => reject(RpcError.fromPayload(safeParse(frame.payload), name)),
                "release",
              );
            default:
              // Events, chunks and stream ends belong to other call kinds.
              return finish(
                () =>
                  reject(localError("Internal", "unexpected frame for call", { procedure: name })),
                "cancel",
              );
          }
        },
        fail: (error: RpcError) => {
          // The connection closed with the call in flight. A query may be retried; a mutation
          // may already have run, so the runtime never says it is safe to resend.
          const retryable = error.local && error.code === "Unavailable" && def.kind === "query";
          const attributed = error.local
            ? localError(error.code, error.message, { retryable, procedure: name })
            : error.forProcedure(name);
          finish(() => reject(attributed), "keep");
        },
      };

      this.#register(handler).then(
        ([c, callId]) => {
          conn = c;
          id = callId;
          if (settled) {
            // Aborted or closed while connecting: nothing was sent.
            c.release(callId);
            return;
          }
          try {
            c.sendJson(Kind.Call, callId, callPayload(def, input, opts.timeoutMs));
          } catch (error) {
            const err =
              error instanceof RpcError
                ? error.forProcedure(name)
                : localError("Internal", "send failed", { procedure: name });
            return finish(() => reject(err), "release");
          }
          const deadline = deadlineMs(def, opts.timeoutMs);
          if (deadline !== undefined) {
            const delay = deadline + this.#options.timeoutSlackMs;
            if (delay <= MAX_TIMER_MS) {
              timer = setTimeout(
                () =>
                  finish(
                    () =>
                      reject(
                        localError("DeadlineExceeded", "deadline exceeded", { procedure: name }),
                      ),
                    "cancel",
                  ),
                delay,
              );
            }
          }
        },
        (error: unknown) => {
          const err =
            error instanceof RpcError
              ? error.forProcedure(name)
              : localError("Unavailable", "connection failed", {
                  retryable: true,
                  procedure: name,
                });
          finish(() => reject(err), "keep");
        },
      );
    });
  }

  subscribe(
    def: ProcedureLike,
    input: unknown,
    opts: CallOptions = {},
  ): SubscriptionHandle<unknown> {
    const sub = new SubscriptionHandle<unknown>(def.name, this.#options.maxBufferedEvents);
    this.#startPush(def, input, opts, sub, Kind.Subscribe);
    return sub;
  }

  stream(def: ProcedureLike, input: unknown, opts: CallOptions = {}): StreamHandle<unknown> {
    const stream = new StreamHandle<unknown>(def.name, this.#options.maxBufferedEvents);
    this.#startPush(def, input, opts, stream, Kind.Call);
    return stream;
  }

  /** Starts a subscription (`Subscribe`) or stream (`Call`) feeding `sink`. */
  #startPush(
    def: ProcedureLike,
    input: unknown,
    opts: CallOptions,
    sink: PushSink,
    kind: Kind,
  ): void {
    const name = def.name;
    const invalid = validateTimeout(opts.timeoutMs, name);
    if (invalid !== undefined) return sink.terminate(invalid);
    const { signal } = opts;
    if (signal?.aborted) return sink.terminate(cancelled(name));
    if (this.#closed)
      return sink.terminate(localError("Unavailable", "client closed", { procedure: name }));

    let conn: Connection | undefined;
    let id: number | undefined;
    const end = (error: RpcError): void => sink.terminate(error);
    const onAbort = (): void => sink.terminate(cancelled(name));
    signal?.addEventListener("abort", onAbort, { once: true });
    this.#live.add(end);

    // Runs exactly once, however the push call ends.
    sink.onEnd((how) => {
      signal?.removeEventListener("abort", onAbort);
      this.#live.delete(end);
      if (conn === undefined || id === undefined) return;
      if (how === "server") conn.release(id);
      else if (kind === Kind.Subscribe) conn.unsubscribe(id);
      else conn.cancel(id);
    });

    this.#register({
      frame: (frame) => sink.frame(frame),
      fail: (error) =>
        sink.terminate(
          error.local
            ? localError(error.code, error.message, { procedure: name })
            : error.forProcedure(name),
          "server",
        ),
    }).then(
      ([c, callId]) => {
        conn = c;
        id = callId;
        if (sink.ended) {
          c.release(callId);
          return;
        }
        try {
          c.sendJson(kind, callId, callPayload(def, input, opts.timeoutMs));
        } catch (error) {
          const err =
            error instanceof RpcError
              ? error.forProcedure(name)
              : localError("Internal", "send failed", { procedure: name });
          c.release(callId);
          conn = undefined;
          sink.terminate(err);
        }
      },
      (error: unknown) => {
        sink.terminate(
          error instanceof RpcError
            ? error.forProcedure(name)
            : localError("Unavailable", "connection failed", { retryable: true, procedure: name }),
          "server",
        );
      },
    );
  }
}

function safeParse(payload: Uint8Array): unknown {
  try {
    return parseJson(payload);
  } catch {
    return undefined;
  }
}

/** How a push call ended: by the server (or connection), or by this side (unsubscribe, abort). */
type EndedBy = "server" | "client";

interface PushSink {
  readonly ended: boolean;
  frame(frame: Frame): void;
  terminate(error: RpcError, by?: EndedBy): void;
  onEnd(listener: (by: EndedBy) => void): void;
}

/**
 * A single-consumer async queue with one terminal state. Values pushed after the end are dropped;
 * values buffered before an error are delivered first, then the error.
 */
class PushQueue<T> {
  #buffer: T[] = [];
  #waiters: Array<{ resolve: (r: IteratorResult<T>) => void; reject: (e: unknown) => void }> = [];
  #done = false;
  #error: RpcError | undefined;

  get done(): boolean {
    return this.#done;
  }

  get size(): number {
    return this.#buffer.length;
  }

  push(value: T): void {
    if (this.#done) return;
    const waiter = this.#waiters.shift();
    if (waiter !== undefined) waiter.resolve({ value, done: false });
    else this.#buffer.push(value);
  }

  /** Ends the queue. `discard` drops undelivered values (explicit unsubscribe). */
  end(error?: RpcError, discard = false): void {
    if (this.#done) return;
    this.#done = true;
    this.#error = error;
    if (discard) this.#buffer = [];
    const waiters = this.#waiters;
    this.#waiters = [];
    for (const w of waiters) {
      if (error !== undefined) w.reject(error);
      else w.resolve({ value: undefined, done: true });
    }
    // Only the first pending reader gets the error; later reads see `done`.
    if (waiters.length > 0) this.#error = undefined;
  }

  next(): Promise<IteratorResult<T>> {
    const value = this.#buffer.shift();
    if (value !== undefined || this.#buffer.length > 0) {
      return Promise.resolve({ value: value as T, done: false });
    }
    if (this.#done) {
      const error = this.#error;
      this.#error = undefined;
      return error !== undefined
        ? Promise.reject(error)
        : Promise.resolve({ value: undefined, done: true });
    }
    return new Promise((resolve, reject) => this.#waiters.push({ resolve, reject }));
  }
}

/** Shared lifecycle of subscriptions and streams. */
abstract class PushHandle<T> implements PushSink {
  protected readonly queue = new PushQueue<T>();
  #ended = false;
  #listeners: Array<(by: EndedBy) => void> = [];
  #iterating = false;

  constructor(
    protected readonly procedure: string,
    protected readonly maxBuffered: number,
  ) {}

  get ended(): boolean {
    return this.#ended;
  }

  abstract frame(frame: Frame): void;

  onEnd(listener: (by: EndedBy) => void): void {
    if (this.#ended) listener("server");
    else this.#listeners.push(listener);
  }

  /** Ends the call with `error`; `by` says whether the server side already forgot it. */
  terminate(error: RpcError, by: EndedBy = "client"): void {
    this.end(by, error, false);
  }

  protected end(by: EndedBy, error: RpcError | undefined, discard: boolean): void {
    if (this.#ended) return;
    this.#ended = true;
    this.settle(error);
    this.queue.end(error, discard);
    const listeners = this.#listeners;
    this.#listeners = [];
    for (const l of listeners) l(by);
  }

  /** Hook for the final result of a stream. */
  protected settle(_error: RpcError | undefined): void {}

  protected enqueue(value: T): void {
    if (this.queue.size >= this.maxBuffered) {
      this.end(
        "client",
        localError("ResourceExhausted", "consumer too slow: buffer limit reached", {
          procedure: this.procedure,
        }),
        false,
      );
      return;
    }
    this.queue.push(value);
  }

  protected iterator(): AsyncIterableIterator<T> {
    if (this.#iterating) throw new TypeError("already being iterated");
    this.#iterating = true;
    const it: AsyncIterableIterator<T> = {
      next: () => this.queue.next(),
      return: (value?: unknown) => {
        this.end("client", undefined, true);
        return Promise.resolve({ value: value as T, done: true });
      },
      throw: (error?: unknown) => {
        this.end("client", undefined, true);
        return Promise.reject(error);
      },
      [Symbol.asyncIterator]: () => it,
    };
    return it;
  }
}

/**
 * A subscription (spec §5): server-push JSON events until `unsubscribe()`, abort, or the server
 * ends it. Iterate once with `for await`; leaving the loop unsubscribes.
 *
 * Termination (provisional, spec Open question 23): an `Error` frame ends the iteration with that
 * error, a `Result` frame ends it normally. After `unsubscribe()` nothing more is delivered.
 */
export class SubscriptionHandle<E> extends PushHandle<E> implements AsyncIterable<E> {
  frame(frame: Frame): void {
    if (this.ended) return;
    switch (frame.kind) {
      case Kind.Event: {
        let value: unknown;
        try {
          value = parseJson(frame.payload);
        } catch {
          return this.end(
            "client",
            localError("Internal", "malformed event", { procedure: this.procedure }),
            false,
          );
        }
        return this.enqueue(value as E);
      }
      case Kind.Error:
        return this.end(
          "server",
          RpcError.fromPayload(safeParse(frame.payload), this.procedure),
          false,
        );
      case Kind.Result:
        return this.end("server", undefined, false);
      default:
        return this.end(
          "client",
          localError("Internal", "unexpected frame for subscription", {
            procedure: this.procedure,
          }),
          false,
        );
    }
  }

  /** Stops the subscription: sends `Unsubscribe` once; undelivered events are dropped. */
  unsubscribe(): void {
    this.end("client", undefined, true);
  }

  [Symbol.asyncIterator](): AsyncIterator<E> {
    return this.iterator();
  }
}

/**
 * A stream call (spec §5, §6), M1 shape: `chunks()` yields the binary `Chunk` payloads in order
 * and `result` settles from `StreamEnd` (the typed summary) or `Error`.
 *
 * Not in M1: credit-based flow control (the runtime sends no `Credit` frames), Worker-side Arrow
 * decoding and the chunk API on top of it. Leaving `chunks()` early cancels the stream.
 */
export class StreamHandle<T> extends PushHandle<Uint8Array> {
  readonly result: Promise<T>;
  #resolve!: (value: T) => void;
  #reject!: (error: RpcError) => void;
  #summary: { value: T } | undefined;

  constructor(procedure: string, maxBuffered: number) {
    super(procedure, maxBuffered);
    this.result = new Promise<T>((resolve, reject) => {
      this.#resolve = resolve;
      this.#reject = reject;
    });
    // A caller that only reads `chunks()` still sees the error there; do not also report it as
    // an unhandled rejection.
    this.result.catch(() => {});
  }

  frame(frame: Frame): void {
    if (this.ended) return;
    switch (frame.kind) {
      case Kind.Chunk:
        if ((frame.flags & FLAG_BINARY) === 0) {
          return this.end(
            "client",
            localError("Internal", "stream chunk is not binary", { procedure: this.procedure }),
            false,
          );
        }
        return this.enqueue(frame.payload);
      case Kind.StreamEnd: {
        try {
          this.#summary = { value: parseJson(frame.payload) as T };
        } catch {
          return this.end(
            "client",
            localError("Internal", "malformed stream summary", { procedure: this.procedure }),
            false,
          );
        }
        return this.end("server", undefined, false);
      }
      case Kind.Error:
        return this.end(
          "server",
          RpcError.fromPayload(safeParse(frame.payload), this.procedure),
          false,
        );
      default:
        return this.end(
          "client",
          localError("Internal", "unexpected frame for stream", { procedure: this.procedure }),
          false,
        );
    }
  }

  protected override settle(error: RpcError | undefined): void {
    if (error !== undefined) this.#reject(error);
    else if (this.#summary !== undefined) this.#resolve(this.#summary.value);
    else this.#reject(cancelled(this.procedure));
  }

  chunks(): AsyncIterable<Uint8Array> {
    const it = this.iterator();
    return { [Symbol.asyncIterator]: () => it };
  }

  /** Cancels the stream. */
  cancel(): void {
    this.end("client", cancelled(this.procedure), true);
  }
}
